import axios from 'axios';
import { CartItem } from './cartService';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as constantsV from '../../constants/constatantsV';

interface ShippingAddress {
  name: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  state: string;
  zipCode: string;
}

export interface Order {
  id: string;
  items: CartItem[];
  totalAmount: number;
  paymentId: string;
  shippingAddress: ShippingAddress;
  status: 'pending' | 'processing' | 'shipped' | 'delivered' | 'cancelled';
  createdAt: string;
}

class OrderService {
  private baseUrl: string = constantsV.BASE_URL + '/orders';
  ORDERS_STORAGE_KEY!: string;
  // Create a new order after successful payment
  async createOrder(orderData: { paymentId: string, amount: number, shippingAddress: ShippingAddress, items: CartItem[] }): Promise<Order> {
    try {
      const token = await AsyncStorage.getItem('auth_token');
      const response = await axios.post<Order>(`${this.baseUrl}/`, orderData, {
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });
      return response.data;
    } catch (error) {
      console.error('Failed to create order:', error);
      throw error;
    }
  }

  // Legacy completeOrder removed: use createOrder above

  // Get all orders for the current user
  async getOrders(): Promise<Order[]> {
    try {
      const token = await AsyncStorage.getItem('auth_token');
      const response = await axios.get<Order[]>(this.baseUrl, {
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });
      return response.data;
    } catch (error) {
      console.error('Failed to get orders:', error);
      return [];
    }
  }
  
  // Get a specific order by ID
  async getOrderById(orderId: string): Promise<Order | null> {
    try {
      const orders = await this.getOrders();
      const order = orders.find(o => o.id === orderId);
      return order || null;
    } catch (error) {
      console.error('Failed to get order:', error);
      return null;
    }
  }
  
  // Update order status
  async updateOrderStatus(orderId: string, status: Order['status']): Promise<boolean> {
    try {
      const orders = await this.getOrders();
      const orderIndex = orders.findIndex(o => o.id === orderId);
      
      if (orderIndex !== -1) {
        orders[orderIndex].status = status;
        await AsyncStorage.setItem(this.ORDERS_STORAGE_KEY, JSON.stringify(orders));
        return true;
      }
      return false;
    } catch (error) {
      console.error('Failed to update order status:', error);
      return false;
    }
  }
}

export default new OrderService();